{
  "material_type": "teaching-simulation",
  "slots": {
    "notice": [
      "教学模拟草稿。研究问题与方案为拟开展工作；真实申请人、团队基础、经费和项目记录尚未提供。"
    ],
    "background": [
      "拟研究的问题是：在文献筛选时，为模型给出的纳入建议同时提供可回到原文的证据位置，是否会改变人工核验的错误率与耗时？这里的“证据位置”指论文内可以打开和核对的页码、段落或表格位置。模型建议纳入一篇论文时，核验者需要确认该论文是否符合事先制定的研究对象、方法和结果要求，不能只看模型摘要。",
      "本教学方案把三个过程分开测量：模型是否找到了符合条件的文献，给出的证据是否支持筛选判断，核验者是否能及时发现错误。这样可以避免仅用最终纳入数量评价整个流程，也便于定位错误发生在哪一步。",
      "上述问题的学术价值目前是研究设想，尚未完成系统文献检索，不能声称“国内外尚无研究”或“首次提出”。正式申请前须检索并阅读与模型辅助系统综述、证据定位、人工核验行为相关的原始研究，形成研究现状及不足的证据矩阵。缺口 G-Q01：目标学科与已有综述范围；G-Q02：已读原始论文及具体页段；G-Q03：本方案相对于已有方法的实质差异。"
    ],
    "research_content": [
      "研究目标是识别证据位置提示对筛选判断的影响及适用条件。拟设置三种流程：人工独立筛选、模型提出建议后人工核验、模型提出建议并附证据位置后人工核验。不同流程应使用相同的纳入标准和可比的文献材料，记录实际模型版本、提示词及检索日期。模型升级后作为新版本处理，不把不同版本混合成一个实验条件。",
      "第一项内容是建立可复核的材料集。根据拟定研究问题制定纳入与排除标准，登记文献标识、全文取得方式及合法使用范围。拟由独立人工判读建立参照，并保存分歧及处理记录。参照判读者数量、资格、是否盲法及分歧解决方法尚待研究者确认，不能在方法中写成已经执行。",
      "第二项内容是比较三个流程的表现。拟记录符合条件文献的发现情况、错误纳入与错误排除、单篇实际核验用时、证据无法打开或不能支持判断的情况。计时起止点、分母、退出条件必须预先规定。不能把“模型给了链接”记作“证据正确”；需另行阅读相应原文位置。",
      "第三项内容是分析影响条件。可考虑按全文长度、表格依赖程度、研究设计复杂性等预先定义的维度进行分层。分层数量须与可获得的样本量相适应。样本量和统计方案尚未确定，需根据主要评价指标、可接受误差和材料可得性论证，不能临时指定一个漂亮的整数。缺口 G-Q04：主要终点及样本量依据；G-Q05：重复判读及顺序效应控制；G-Q06：模型调用预算和失败处理规则。",
      "拟定技术路线为：明确研究问题及筛选标准；取得并登记文献；建立独立人工参照；固定三种流程与版本；收集判断、定位证据与用时；核对分母和异常记录；比较结果并解释限制。对应可编辑文件为 route.mmd。路线中的每个“比较”都是拟开展工作，尚无结果。",
      "年度安排及项目期限以正式指南和申请人条件为准。本案例暂不填写月份、经费或预期论文数量。可能的交付包括数据字典、可复现筛选记录、错误分类表及方法报告；具体考核指标需在申报类别明确后与指南逐项对应。"
    ],
    "research_foundation": [
      "未提供申请人的相关论文、项目、工具、试验或预实验记录，保留待补充。公开模板和本课程样例不能作为团队研究基础。拟核对的可行性条件包括合法全文取得、稳定的材料读取工具、版本可记录的模型服务，以及具备学科判断能力的核验人员。"
    ],
    "conditions": [
      "已有设备、数据权限、学校伦理或数据管理要求均待申请人确认。应说明能够在本地处理的材料与需要发送给外部服务的材料；未公开资料未经授权不外传。"
    ],
    "ongoing_projects": [
      "待申请人提供。不能用“无”替代尚未询问的事实。"
    ],
    "completed_projects": [
      "待申请人提供并核对项目编号、期限及成果。课程不生成证明或结题信息。"
    ],
    "same_year_applications": [
      "待申请人提供同年申请信息，不能将未询问的事实填为“无”。"
    ],
    "unit_consistency": [
      "待申请人与参与人员确认同年申请的单位信息。"
    ],
    "ongoing_unit_consistency": [
      "待申请人与参与人员确认在研项目与单位信息。"
    ],
    "professional_titles": [
      "待申请人及参与人员确认职称。"
    ],
    "ai_use": [
      "本文件的教学方案与说明由 AI 协作起草；实际申请须按使用记录说明位置和内容，并由申请人核对。"
    ],
    "other_declarations": [
      "按原模板逐项填写同年申请、单位一致性、职称及其他要求。涉及生成式人工智能辅助的位置与内容，应依据实际使用记录说明。本文件为 AI 协作形成的教学草稿，该说明不能替代真实申请人的当年申报声明。所有个人、单位、项目与签名信息保持待确认。"
    ]
  },
  "source_notes": [
    "2026 面上项目原模板、填写说明和下载记录见 templates/acquisition.json。"
  ],
  "unresolved_questions": [
    "研究期限、样本量依据、真实团队与已有项目材料待提供。"
  ]
}

